from functools import lru_cache

MOD = 1000000007

def solve(n_str):
    lines = n_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    occupied = set()
    for i in range(n):
        if arr[i] != -1:
            occupied.add(arr[i])

    available = [i + 1 for i in range(n) if (i + 1) not in occupied]
    empty_positions = [i + 1 for i in range(n) if arr[i] == -1]

    mapping = {v: i for i, v in enumerate(empty_positions)}

    m = len(empty_positions)

    @lru_cache(None)
    def dp(used_mask):
        pos_idx = bin(used_mask).count('1')
        if pos_idx == m:
            return 1

        target_pos = empty_positions[pos_idx]
        total = 0

        for i in range(m):
            if not (used_mask & (1 << i)):
                num = available[i]
                if num != target_pos:
                    total = (total + dp(used_mask | (1 << i))) % MOD

        return total

    result = dp(0)
    return str(result) + '\n'

def solution(input_string):
    return solve(input_string)
