def solution(input_str):
    l, r = map(int, input_str.split())

    # Sieve up to sqrt(r) to find small primes
    sqrt_r = int(r**0.5) + 1
    is_prime_small = [True] * sqrt_r
    if sqrt_r > 0:
        is_prime_small[0] = False
    if sqrt_r > 1:
        is_prime_small[1] = False

    for i in range(2, int(sqrt_r**0.5) + 1):
        if is_prime_small[i]:
            for j in range(i * i, sqrt_r, i):
                is_prime_small[j] = False

    primes = [i for i, p in enumerate(is_prime_small) if p]

    # Count primes in [l, r] that are either 2 or ≡ 1 (mod 4)
    # These are exactly the primes that can be written as sum of two squares
    count = 0
    segment_size = 100000

    start = l
    while start <= r:
        end = min(start + segment_size, r + 1)
        segment_len = end - start

        # Initialize segment as all potentially prime
        is_prime_segment = [True] * segment_len

        # Mark composites in the segment using small primes
        for p in primes:
            if p * p > end:
                break

            # Find first multiple of p >= start
            # We start from max(p*p, firstmultiple>=start) to avoid over-marking multiples of smaller primes
            first = max(p * p, (start + p - 1) // p * p)

            if first < end:
                first_idx = first - start
                for j in range(first_idx, segment_len, p):
                    is_prime_segment[j] = False

        # Count valid primes in this segment
        for i in range(segment_len):
            num = start + i
            if is_prime_segment[i] and (num == 2 or num % 4 == 1):
                count += 1

        start = end

    return str(count) + '\n'
