                if nxt != 0:
                    return False
            elif nxt == 0:
                # r = 0 from here onward
                for m in range(k + 2, len(seq)):
                    if seq[m] != 0:
                        return False
            else:
                # Both non-zero, check cross product
                if nxt * den != curr * num:
                    return False

        return True

    # Case 1: Check if already a GP
    if check_g(seq):
        return "0\n"

    # Case 2: Try removing each element and check
    for skip in range(n):
        temp = seq[:skip] + seq[skip+1:]
        if check_g(temp):
