def solution(input_str: str) -> str:
    """
    Solve the grid coloring problem.
    Given an n x m grid with some vertices colored (1-4) and others unpainted (0),
    find a valid 4-coloring or determine it's impossible.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    def to_color(c):
        return int(c) if c in '1234' else 0

    def get_neighbors(r, c):
        """Get all 8 neighbors of position (r, c)"""
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors.append((nr, nc))
        return neighbors

    def is_valid_coloring(g):
        """Check if current grid has any invalid adjacent colors"""
        for r in range(n):
            for c in range(m):
                color = g[r][c]
                if color == 0:
                    continue
                for nr, nc in get_neighbors(r, c):
                    neighbor_color = g[nr][nc]
                    if neighbor_color != 0 and neighbor_color == color:
                        return False
        return True

    # Check initial configuration for conflicts
    if not is_valid_coloring(grid):
        return '0\n'

    # Fill 0 positions using a simple greedy approach
    # Try colors 1-4 for each position, checking validity

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '0':
                # Try each color 1-4
                found = False
                for color in range(1, 5):
                    grid[r][c] = str(color)
                    if is_valid_coloring(grid):
                        found = True
                        break
                    grid[r][c] = '0'  # backtrack

                if not found:
                    return '0\n'

    # Output result
    return '\n'.join(''.join(row) for row in grid) + '\n'
