    alphabet = [chr(ord('a') + i) for i in range(l)]
    vocab_type = {chr(ord('a') + i): vowel_str[i] for i in range(l)}

    def get_type(char):
        return vocab_type.get(char, 'C')

    def check_validity(word):
        for pos1, t1, pos2, t2 in rules:
            if get_type(word[pos1]) == t1 and get_type(word[pos2]) != t2:
                return False
        return True

    def can_complete(fixed):
        req = [None] * n
        for i in range(n):
            if i in fixed:
                req[i] = fixed[i]

        changed = True
        while changed:
            changed = False
            for pos1, t1, pos2, t2 in rules:
                if pos1 in fixed and fixed[pos1] == t1:
                    if req[pos2] is None:
                        req[pos2] = t2
                        changed = True
                    elif req[pos2] != t2:
                        return False

        for i in range(n):
            if i in fixed:
                if req[i] != fixed[i] and req[i] is not None:
                    return False

        return True

    def backtrack(pos, word, prefix_same):
        if pos == n:
            return True

        start = 0 if not prefix_same else alphabet.index(s[pos])
        for idx in range(start, len(alphabet)):
            ch = alphabet[idx]
            new_word = word + [ch]
            fixed = {i: get_type(new_word[i]) for i in range(pos + 1)}
            prefix_same = prefix_same and (ch == s[pos])

            if not check_validity(new_word):
                continue

            if not can_complete(fixed):
                continue

            if backtrack(pos + 1, new_word, prefix_same):
                return True

            new_word.pop()

    # Try to build the smallest valid word >= s
    result = []

    def try_build(prefix):
        if len(prefix) == n:
            if check_validity(prefix):
                return prefix
            return None

        pos = len(prefix)
        start = 0
        if len(prefix) > 0:
            # Check if we've gone greater than s already
            gone_greater = any(prefix[i] > s[i] for i in range(pos))
            gone_greater = gone_greater or any(prefix[i] == s[i] for i in range(pos))
            start = alphabet.index(s[pos]) if not gone_greater else 0
        else:
            start = alphabet.index(s[pos])

        for idx in range(start, len(alphabet)):
            ch = alphabet[idx]
            new_prefix = prefix + [ch]
            fixed = {i: get_type(new_prefix[i]) for i in range(pos + 1)}

            if not check_validity(new_prefix):
                continue

            if not can_complete(fixed):
                continue

            result_inner = try_build(new_prefix)
            if result_inner is not None:
                return result_inner

    result = try_build([])
    if result:
        return ''.join(result)
    else:
        return "-1"
