            pairs.append((cost[i][j], total_cost, i, j))

    pairs.sort(key=lambda x: x[1])  # Sort by total cost

    matching = [None] * N
    for _, _, i, j in pairs:
        if matching[i] is None and matching[j] is None:
            matching[i] = j
            matching[j] = i
            if all(m is not None for m in matching):
                break

    # Check if we have a perfect matching
    if any(m is None for m in matching):
        return '-1'

    # Iteratively fix any blocking pairs
    for _ in range(N * N):
        improved = False
        for i in range(N):
