    for i in range(m):
        parts = lines[i+1].split()
        edges.append((int(parts[0]), int(parts[1]), i))

    # Check if two edges cross
    def check_crossing(e1, e2):
        a, b, i1 = e1
        c, d, i2 = e2
        low_a, high_a = min(a, b), max(a, b)
        low_c, high_c = min(c, d), max(c, d)

        # Remove the case where edges are the same or share an endpoint
        if low_a == low_c or low_a == high_c or high_a == low_c or high_a == high_c:
            return False

        # Edges cross if one endpoint of e2 is strictly between endpoints of e1
        # on both sides (i.e., interleaving)
        if low_c > low_a and low_c < high_a and high_c > low_a and high_c < high_a:
            return True

    # Build graph where edges are nodes and crossing edges have edges between them
    crossing_graph = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i+1, m):
            if check_crossing(edges[i], edges[j]):
                crossing_graph[i].append(j)
                crossing_graph[j].append(i)

    # Check if the graph is bipartite (2-colorable)
    colors = [None] * m
    solution = []

    for i in range(m):
        if colors[i] is None:
            colors[i] = 0
            queue = [i]
            while queue:
                u = queue.pop(0)
                if colors[u] == 0:
                    solution.append('i')
                else:
                    solution.append('o')

                for v in crossing_graph[u]:
                    if colors[v] is None:
                        colors[v] = 1 - colors[u]
                        queue.append(v)
