Looking at this problem, I need to understand the key rules:

1. John starts with no items and can make exchanges once per day
2. When exchanging items: he can give some items he has and receive some items he doesn't have
3. The constraint: sum(received_items) - sum(items_given_up) ≤ d (can't lose too much value per day)
4. Goal: maximize total value John can own, and find minimum days to achieve it

This is essentially a BFS problem where each state is a reachable sum, and we track the minimum days to reach each sum. Let me write a solution:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, d = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    if n == 0:
        return '0 0'

    # Calculate all possible subset sums
    from itertools import combinations

    total_sum = sum(c)

    # all_subset_sums is the set of all sums of possible non-exclusive item sets
    all_subset_sums = {0}
    mask = 1 << n
    for i in range(mask):
        current_sum = 0
        for j in range(n):
            if i & (1 << j):
                current_sum += c[j]
        all_subset_sums.add(current_sum)

    # Convert to sorted list for efficient processing
    sorted_sums = sorted(list(all_subset_sums))

    # reach[sum] = minimum days needed to own items with total value = sum
    reach = {s: float('inf') for s in sorted_sums}
    reach[0] = 0  # Start with no items on day 0

    visited = set()
    visited.add(0)

    # BFS-like approach: process days
    day = 0
    changed = True

    while changed:
        changed = False
        day += 1
        next_visited = set()

        current_reachable = sorted([s for s in visited])

        # For each currently reachable state, find all states we can reach in 1 more day
        for current_sum in current_reachable:
            for next_sum in all_subset_sums:
                # We can go from current_sum to next_sum in 1 exchange/day
                # The constraint is: next_sum - current_sum <= d
                if next_sum - current_sum <= d:
                    # Find minimum days to reach next_sum
                    if (day + reach[current_sum]) < reach[next_sum]:
                        old_days = reach[next_sum]
                        reach[next_sum] = day + reach[current_sum]
                        if old_days != float('inf'):
                            if next_sum not in visited:
                                next_visited.add(next_sum)
                                changed = True

        visited.update(next_visited)

    # Find the maximum sum and minimum days
    max_sum = 0
    min_days = 0

    for s in sorted_sums:
        if reach[s] < float('inf'):
            if s > max_sum:
                max_sum = s
                min_days = reach[s]

    return f"{max_sum} {min_days}"
