        all_subset_sums.add(current_sum)

    sorted_sums = sorted(list(all_subset_sums))

    # reach[sum] = minimum days to reach state with total item value = sum
    # Day 0 is starting with no items
    reach = {s: float('inf') for s in sorted_sums}
    reach[0] = 0

    visited = {0}

    # BFS to find minimum days
    day = 0
    while True:
        day += 1
        newly_reachable = set()

        for prev_sum in visited:
            days_needed = 1 + reach[prev_sum]

            for target_sum in sorted_sums:
                if target_sum - prev_sum <= d and target_sum not in visited:
                    reach[target_sum] = min(reach[target_sum], days_needed)
                    newly_reachable.add(target_sum)

        visited.update(newly_reachable)

        # Stop if no new states are found
        if len(newly_reachable) == 0:
            break

        # Safety: maximum 2000 days
        if day > 2000:
            break

    # Find the maximum sum achievable and minimum days
    possible_sums = [s for s in visited if reach[s] < float('inf')]

    if not possible_sums:
        return '0 0'

    max_sum = max(possible_sums)
    min_days = reach[max_sum]

    return f"{max_sum} {min_days}"
