                sums.add(sum(combo))
        return sums

    left_sums = gen_subset_sums(left_part)
    right_sums = gen_subset_sums(right_part)

    # All possible sums combining left and right parts
    all_possible = set()
    for ls in left_sums:
        for rs in right_sums:
            all_possible.add(ls + rs)

    sorted_sums = sorted(all_possible)

    # reach[sum] = minimum days to acquire items with total value = sum
    reach = {s: float('inf') for s in sorted_sums}
    reach[0] = 0

    visited = {0}

