    diffs = [(a[i+1] - a[i]) % m for i in range(n - 1)]

    # Get the most common non-zero difference
    from collections import Counter
    if diffs:
        unique_diffs = Counter(diff for diff in diffs if diff != 0)
    else:
        unique_diffs = {}

    candidate_diffs = unique_diffs.most_common()

    for d_test, count in candidate_diffs:
        if count < 1:
            continue

        # Try each starting element with this difference
        for start in a:
            gen = set()
            curr = start
            valid = True
            for _ in range(n):
                if curr in gen:
                    valid = False
                    break
                gen.add(curr)
                curr = (curr + d_test) % m

            if valid and gen == input_set:
                return f"{start} {d_test}\n"

