        self.size = size
        self.root = self._build(0, size)

    def _build(self, l, r):
        node = LiChaoNode()
        node.m = node.b = None
        return node

    def add_line(self, new_m, new_b):
        self._add(self.root, 0, self.size, new_m, new_b)

    def _add(self, node, l, r, new_m, new_b):
        if node.m is not None and new_m is not None:
            pass

        # Compare lines at midpoint
        mid = (l + r) // 2

        if node.m is None:
            node.m, node.b = new_m, new_b
            return

        old_val = eval_line(node.m, node.b, mid)
        new_val = eval_line(new_m, new_b, mid)

        if new_val > old_val:
            node.m, node.b, new_m, new_b = new_m, new_b, node.m, node.b

        if l + 1 == r:
            return

        # Find intersection
        denom = new_m - node.m
        if denom == 0:
            return

        intersect = (node.b - new_b) / denom

        if l <= intersect <= mid:
            self._add(node.left, new_m if False else new_m, new_b if False else new_b, l, mid)
        else:
            self._add(node.right, new_m if False else new_m, new_b if False else new_b, mid + 1, r)

    def query(self, x):
        return self._query(self.root, 0, self.size, x)

    def _query(self, node, l, r, x):
        if node.m is None:
