def solution(n_str):
    n = int(n_str)

    # BFS to find minimum operations from n to 0
    # Each operation: subtract a digit present in the current number

    from collections import deque

    def get_digits(num):
        """Return the set of unique digits in num"""
        return set(int(d) for d in str(num))

    def solve_bfs(n):
        if n == 0:
            return 0

        # Queue stores (number, distance)
        queue = deque([(n, 0)])
        visited = {n}

        while queue:
            current, dist = queue.popleft()

            # Get all unique digits in current number
            digits = get_digits(current)

            # Try subtracting each digit
            for d in digits:
                new_num = current - d

                # If we reached 0, return the distance + 1
                if new_num == 0:
                    return dist + 1

                # If not visited and positive, add to queue
                if new_num > 0 and new_num not in visited:
                    visited.add(new_num)
                    queue.append((new_num, dist + 1))

        return -1  # Should not happen

    # For very large numbers (n > 10^14), we need a more efficient approach
    # because BFS state space becomes too large
    if n <= 10**14:
        return str(solve_bfs(n))
    else:
        # For larger inputs, use dynamic programming with digit-based approach
        return str(solve_dp(n))

def solve_dp(n):
    """DP solution for very large numbers"""
    memo = {}

    def dp(num):
        if num == 0:
            return 0
        if num in memo:
            return memo[num]

        digits = set(int(d) for d in str(num))
        min_ops = float('inf')

        for d in digits:
            new_num = num - d
            if new_num > 0:
                ops = dp(new_num)
                if ops + 1 < min_ops:
                    min_ops = ops + 1

        memo[num] = min_ops if min_ops != float('inf') else 0
        return memo[num]

    return dp(n)

