from collections import deque

def solution(n_str):
    """
    Solve the magic number subtraction problem.

    Given a magic number n, repeatedly subtract a digit that appears in the number
    until reaching 0. Find the minimum number of operations required.

    Args:
        n_str: String representation of the magic number

    Returns:
        String representation of the minimum number of operations
    """
    n = int(n_str.strip())

    if n == 0:
        return "0"

    def bfs_solve(num):
        """BFS to find minimum operations from num to 0"""
        queue = deque([(num, 0)])
        visited = {num}

        while queue:
            curr, dist = queue.popleft()

            # Get all unique digits in current number
            digits = set(int(d) for d in str(curr))

            # Try subtracting each digit
            for d in digits:
                nxt = curr - d

                # Found target (0)
                if nxt == 0:
                    return dist + 1

                # Add to queue if valid and not visited
                if nxt > 0 and nxt not in visited:
                    visited.add(nxt)
                    queue.append((nxt, dist + 1))

        return -1  # Should never reach here

    return str(bfs_solve(n))
